package com.levelinghelper;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HintArrowType;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

/** Cooperates with server and other plugin arrows instead of claiming the shared arrow every tick. */
final class HintArrowController
{
	private final Client client;
	private NPC npc;
	private WorldPoint point;

	@Inject
	HintArrowController(Client client)
	{
		this.client = client;
	}

	void update(boolean enabled, NPC targetNpc, WorldPoint targetPoint)
	{
		if (!enabled || client.getGameState() != GameState.LOGGED_IN)
		{
			clear();
			return;
		}
		if (client.hasHintArrow() && !ownsCurrent())
		{
			npc = null;
			point = null;
			return;
		}
		if (targetNpc != null)
		{
			if (npc != targetNpc || !ownsCurrent())
			{
				client.setHintArrow(targetNpc);
			}
			npc = targetNpc;
			point = null;
		}
		else if (targetPoint != null)
		{
			if (!targetPoint.equals(point) || !ownsCurrent())
			{
				client.setHintArrow(targetPoint);
			}
			point = targetPoint;
			npc = null;
		}
		else
		{
			clear();
		}
	}

	void clear()
	{
		if (ownsCurrent())
		{
			client.clearHintArrow();
		}
		npc = null;
		point = null;
	}

	private boolean ownsCurrent()
	{
		return npc != null && client.getHintArrowType() == HintArrowType.NPC && client.getHintArrowNpc() == npc
			|| point != null && client.getHintArrowType() == HintArrowType.COORDINATE && point.equals(client.getHintArrowPoint());
	}
}

package com.levelinghelper;

import com.levelinghelper.model.ItemCategory;
import java.util.Arrays;
import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.Skill;
import net.runelite.api.Varbits;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/** Read-only classifications of actual carried/banked item definitions. */
final class ItemRules
{
	private static final int[] HERBS = {ItemID.GRIMY_GUAM_LEAF, ItemID.GRIMY_MARRENTILL, ItemID.GRIMY_TARROMIN,
		ItemID.GRIMY_HARRALANDER, ItemID.GRIMY_RANARR_WEED, ItemID.GRIMY_TOADFLAX, ItemID.GRIMY_IRIT_LEAF,
		ItemID.GRIMY_AVANTOE, ItemID.GRIMY_KWUARM, ItemID.GRIMY_SNAPDRAGON, ItemID.GRIMY_CADANTINE,
		ItemID.GRIMY_LANTADYME, ItemID.GRIMY_DWARF_WEED, ItemID.GRIMY_TORSTOL};
	private static final int[] CLEAN_LEVELS = {3, 5, 11, 20, 25, 30, 40, 48, 54, 59, 65, 67, 70, 75};
	private static final int[] SEEDS = {ItemID.GUAM_SEED, ItemID.MARRENTILL_SEED, ItemID.TARROMIN_SEED,
		ItemID.HARRALANDER_SEED, ItemID.RANARR_SEED, ItemID.TOADFLAX_SEED, ItemID.IRIT_SEED, ItemID.AVANTOE_SEED,
		ItemID.KWUARM_SEED, ItemID.SNAPDRAGON_SEED, ItemID.CADANTINE_SEED, ItemID.LANTADYME_SEED,
		ItemID.DWARF_WEED_SEED, ItemID.TORSTOL_SEED};
	private static final int[] PLANT_LEVELS = {9, 14, 19, 26, 32, 38, 44, 50, 56, 62, 67, 73, 79, 85};
	private static final int[] SAPLINGS = {ItemID.OAK_SAPLING, ItemID.WILLOW_SAPLING, ItemID.MAPLE_SAPLING, ItemID.YEW_SAPLING,
		ItemID.MAGIC_SAPLING, ItemID.APPLE_SAPLING, ItemID.BANANA_SAPLING, ItemID.ORANGE_SAPLING, ItemID.CURRY_SAPLING,
		ItemID.PINEAPPLE_SAPLING, ItemID.PAPAYA_SAPLING, ItemID.PALM_SAPLING};
	private static final int[] TREE_LEVELS = {15, 30, 45, 60, 75, 27, 33, 39, 42, 51, 57, 68};
	private static final int[] POUCH_TYPES = {Varbits.RUNE_POUCH_RUNE1, Varbits.RUNE_POUCH_RUNE2, Varbits.RUNE_POUCH_RUNE3, Varbits.RUNE_POUCH_RUNE4};
	private static final int[] POUCH_AMOUNTS = {Varbits.RUNE_POUCH_AMOUNT1, Varbits.RUNE_POUCH_AMOUNT2, Varbits.RUNE_POUCH_AMOUNT3, Varbits.RUNE_POUCH_AMOUNT4};

	private final Client client;
	private final ItemManager items;

	ItemRules(Client client, ItemManager items)
	{
		this.client = client;
		this.items = items;
	}

	boolean matches(ItemCategory category, int id)
	{
		ItemComposition item = items.getItemComposition(id);
		if (item == null || item.getNote() != -1 || item.getPlaceholderTemplateId() != -1
			|| item.isMembers() && !client.getWorldType().contains(WorldType.MEMBERS)) return false;
		String name = item.getName() == null ? "" : item.getName().toLowerCase(Locale.ROOT);
		ItemStats stats = items.getItemStats(id);
		ItemEquipmentStats equipment = stats == null ? null : stats.getEquipment();
		switch (category)
		{
			case FOOD:
				return !name.contains("poison") && !name.contains("rock cake") && !name.contains("nightshade")
					&& !name.contains("rotten") && (hasAction(item, "Eat")
						|| hasAction(item, "Drink") && (name.contains("wine") || name.contains("saradomin brew") || name.contains("guthix rest")));
			case MELEE_WEAPON:
				return equipment != null && equipment.getSlot() == 3
					&& (equipment.getAstab() > 0 || equipment.getAslash() > 0 || equipment.getAcrush() > 0);
			case RANGED_WEAPON:
				return equipment != null && equipment.getSlot() == 3 && (equipment.getArange() > 0 || equipment.getRstr() > 0);
			case SELF_AMMO_WEAPON:
				return equipment != null && equipment.getSlot() == 3 && (equipment.getArange() > 0 || equipment.getRstr() > 0)
					&& !name.contains("empty") && !name.contains("(u)") && !name.contains("inactive")
					&& (item.isStackable() || name.contains("crystal bow") || name.contains("faerdhinen")
						|| name.contains("blowpipe") || name.contains("craw's bow") || name.contains("webweaver"));
			case POWERED_STAFF:
				return equipment != null && equipment.getSlot() == 3 && !name.contains("uncharged") && !name.contains("(u)")
					&& (name.contains("trident") || name.contains("sanguinesti") || name.contains("tumeken") || name.contains("warped sceptre"));
			case AMMUNITION:
				return equipment != null && equipment.getSlot() == 13 && equipment.getRstr() > 0;
			case GRIMY_HERB: return leveled(id, HERBS, CLEAN_LEVELS, Skill.HERBLORE);
			case HERB_SEED: return leveled(id, SEEDS, PLANT_LEVELS, Skill.FARMING);
			case SAPLING: return leveled(id, SAPLINGS, TREE_LEVELS, Skill.FARMING);
			case LEATHER: return id == ItemID.LEATHER || id == ItemID.HARD_LEATHER && client.getRealSkillLevel(Skill.CRAFTING) >= 28;
			case PLANK: return id == ItemID.PLANK || id == ItemID.OAK_PLANK || id == ItemID.TEAK_PLANK || id == ItemID.MAHOGANY_PLANK;
			case FOUNDRY_METAL:
				return id == ItemID.BRONZE_BAR || id == ItemID.IRON_BAR || id == ItemID.STEEL_BAR
					|| id == ItemID.MITHRIL_BAR || id == ItemID.ADAMANTITE_BAR || id == ItemID.RUNITE_BAR;
			default: return false;
		}
	}

	private boolean leveled(int id, int[] ids, int[] levels, Skill skill)
	{
		for (int i = 0; i < ids.length; i++) if (ids[i] == id) return client.getRealSkillLevel(skill) >= levels[i];
		return false;
	}

	private boolean hasAction(ItemComposition item, String action)
	{
		return item.getInventoryActions() != null && Arrays.asList(item.getInventoryActions()).contains(action);
	}

	int pouchCount(int itemId)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null) return 0;
		int slots = inventory.count(ItemID.DIVINE_RUNE_POUCH) > 0 || inventory.count(ItemID.DIVINE_RUNE_POUCH_L) > 0 ? 4
			: inventory.count(ItemID.RUNE_POUCH) > 0 || inventory.count(ItemID.RUNE_POUCH_L) > 0 ? 3 : 0;
		if (slots == 0 || client.getEnum(982) == null) return 0;
		long count = 0;
		for (int i = 0; i < slots; i++)
		{
			int type = client.getVarbitValue(POUCH_TYPES[i]);
			if (type > 0 && client.getEnum(982).getIntValue(type) == itemId)
			{
				count += Math.max(0, client.getVarbitValue(POUCH_AMOUNTS[i]));
			}
		}
		return (int) Math.min(Integer.MAX_VALUE, count);
	}
}

package com.levelinghelper;

import com.levelinghelper.model.AccountMode;
import com.levelinghelper.model.TrainingStyle;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(LevelingHelperConfig.GROUP)
public interface LevelingHelperConfig extends Config
{
	String GROUP = "levelinghelper";

	@ConfigItem(
		keyName = "showTiles",
		name = "Mark the destination",
		description = "Highlight the tile you are walking to.",
		position = 2
	)
	default boolean showTiles()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showObjects",
		name = "Highlight targets",
		description = "Highlight the NPCs and objects for the current step.",
		position = 3
	)
	default boolean showObjects()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showArrow",
		name = "Target arrows",
		description = "Show a target arrow in the scene and a direction marker on the minimap.",
		position = 4
	)
	default boolean showArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHintArrow",
		name = "Native hint arrow",
		description = "Also use the game's shared yellow arrow when no other plugin or server arrow is active.",
		position = 9
	)
	default boolean showHintArrow()
	{
		return false;
	}

	@ConfigItem(
		keyName = "allowWilderness",
		name = "Include Wilderness routes",
		description = "Allow routes where other players can kill you and take your items. Disabled by default.",
		position = 10
	)
	default boolean allowWilderness()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showWorldMap",
		name = "World map marker",
		description = "Mark the destination on the world map.",
		position = 5
	)
	default boolean showWorldMap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoAdvance",
		name = "Auto-advance steps",
		description = "Move to the next step when you arrive, finish at the bank, or fill your inventory.",
		position = 6
	)
	default boolean autoAdvance()
	{
		return true;
	}

	@Range(min = 3, max = 40)
	@ConfigItem(
		keyName = "arrivalDistance",
		name = "Arrival distance",
		description = "Maximum distance in tiles that counts as arriving. Routes may require a tighter radius.",
		position = 7
	)
	default int arrivalDistance()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color used for the destination and the targets.",
		position = 8
	)
	default Color highlightColor()
	{
		return new Color(80, 210, 140);
	}

	@ConfigItem(
		keyName = "accountMode",
		name = "Account mode",
		description = "Saved free-to-play or members choice.",
		hidden = true
	)
	default AccountMode accountMode()
	{
		return AccountMode.F2P;
	}

	@ConfigItem(
		keyName = "trainingStyle",
		name = "Training style",
		description = "Saved training style.",
		hidden = true
	)
	default TrainingStyle trainingStyle()
	{
		return TrainingStyle.BALANCED;
	}

	@ConfigItem(
		keyName = "goalLevel",
		name = "Goal level",
		description = "Saved goal level.",
		hidden = true
	)
	default int goalLevel()
	{
		return 99;
	}

	@ConfigItem(
		keyName = "skillName",
		name = "Skill",
		description = "Saved skill.",
		hidden = true
	)
	default String skillName()
	{
		return "Woodcutting";
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.DirectionArrow;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** Independent of the game's single shared hint arrow. This overlay never handles clicks. */
class LevelingHelperMinimapOverlay extends Overlay
{
	private final Client client;
	private final LevelingHelperPlugin plugin;
	private final LevelingHelperConfig config;

	@Inject
	LevelingHelperMinimapOverlay(Client client, LevelingHelperPlugin plugin, LevelingHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.active() || !config.showArrow() || client.getGameState() != GameState.LOGGED_IN
			|| client.getVarbitValue(VarbitID.MINIMAP_STATE) != 0)
		{
			return null;
		}
		Player player = client.getLocalPlayer();
		WorldPoint target = plugin.guidanceTarget();
		if (player == null || target == null || target.getPlane() != player.getWorldLocation().getPlane())
		{
			return null;
		}
		Widget map = client.getWidget(!client.isResized() ? InterfaceID.Toplevel.MINIMAP
			: client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
				? InterfaceID.ToplevelPreEoc.MINIMAP : InterfaceID.ToplevelOsrsStretch.MINIMAP);
		if (map == null || map.isHidden())
		{
			return null;
		}
		Rectangle bounds = map.getBounds();
		double zoom = client.getMinimapZoom();
		if (zoom <= 0)
		{
			return null;
		}
		WorldPoint origin = player.getWorldLocation();
		Polygon arrow = DirectionArrow.polygon((target.getX() - origin.getX()) * zoom,
			(target.getY() - origin.getY()) * zoom, client.getCameraYawTarget(), bounds);
		if (arrow != null)
		{
			Graphics2D marker = (Graphics2D) graphics.create();
			marker.clip(new Ellipse2D.Double(bounds.x, bounds.y, bounds.width, bounds.height));
			marker.setColor(config.highlightColor());
			marker.fill(arrow);
			marker.setColor(Color.BLACK);
			marker.setStroke(new BasicStroke(2));
			marker.draw(arrow);
			marker.dispose();
		}
		return null;
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.GuideController;
import com.levelinghelper.model.GuideStep;
import com.levelinghelper.model.TrainingMethod;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.GroundObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class LevelingHelperOverlay extends Overlay
{
	private final Client client;
	private final LevelingHelperPlugin plugin;
	private final LevelingHelperConfig config;

	@Inject
	LevelingHelperOverlay(Client client, LevelingHelperPlugin plugin, LevelingHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GuideController controller = plugin.controller();
		if (!plugin.active() || !controller.running() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		GuideStep step = plugin.currentStep();
		TrainingMethod method = controller.method();
		if (step == null || method == null)
		{
			return null;
		}
		Color color = config.highlightColor();
		if (config.showTiles())
		{
			renderTile(graphics, plugin.guidanceTarget(), color);
		}
		if (config.showObjects())
		{
			renderTargets(graphics, color);
		}
		if (config.showArrow())
		{
			renderArrow(graphics, plugin.guidanceTarget(), color);
		}
		return null;
	}

	private void renderTile(Graphics2D graphics, WorldPoint target, Color color)
	{
		if (target == null || target.getPlane() != client.getPlane())
		{
			return;
		}
		LocalPoint local = LocalPoint.fromWorld(client, target);
		if (local == null)
		{
			return;
		}
		Polygon polygon = Perspective.getCanvasTilePoly(client, local);
		if (polygon != null)
		{
			OverlayUtil.renderPolygon(graphics, polygon, color, new Color(color.getRed(), color.getGreen(), color.getBlue(), 40), new BasicStroke(2));
		}
	}

	private void renderTargets(Graphics2D graphics, Color color)
	{
		for (NPC npc : plugin.highlightedNpcs())
		{
			Shape hull = npc.getConvexHull();
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
			}
		}
		for (TileObject object : plugin.highlightedObjects())
		{
			Shape hull = hull(object);
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
			}
		}
	}

	private void renderArrow(Graphics2D graphics, WorldPoint target, Color color)
	{
		if (target == null || target.getPlane() != client.getPlane())
		{
			return;
		}
		Point anchor = targetAnchor(target);
		if (anchor == null)
		{
			return;
		}
		// A small downward arrow above the target, rather than a screen-edge triangle.
		int x = anchor.getX();
		int y = anchor.getY();
		Polygon arrow = new Polygon(new int[]{x - 4, x + 4, x + 4, x + 10, x, x - 10, x - 4},
			new int[]{y - 27, y - 27, y - 14, y - 14, y - 4, y - 14, y - 14}, 7);
		Rectangle viewport = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
			client.getViewportWidth(), client.getViewportHeight());
		if (!viewport.contains(arrow.getBounds()))
		{
			return;
		}
		Graphics2D marker = (Graphics2D) graphics.create();
		marker.setColor(color);
		marker.fill(arrow);
		marker.setColor(Color.BLACK);
		marker.setStroke(new BasicStroke(2));
		marker.draw(arrow);
		marker.dispose();
	}

	private Point targetAnchor(WorldPoint target)
	{
		for (NPC npc : plugin.highlightedNpcs())
		{
			if (target.equals(npc.getWorldLocation()))
			{
				return Perspective.localToCanvas(client, npc.getLocalLocation(), target.getPlane(), npc.getLogicalHeight() + 40);
			}
		}
		for (TileObject object : plugin.highlightedObjects())
		{
			if (target.equals(object.getWorldLocation()))
			{
				Shape shape = hull(object);
				if (shape != null)
				{
					Rectangle bounds = shape.getBounds();
					return new Point((int) bounds.getCenterX(), bounds.y - 4);
				}
			}
		}
		LocalPoint local = LocalPoint.fromWorld(client, target);
		return local == null ? null : Perspective.localToCanvas(client, local, target.getPlane(), 100);
	}

	private static Shape hull(TileObject object)
	{
		if (object instanceof GameObject)
		{
			return ((GameObject) object).getConvexHull();
		}
		if (object instanceof WallObject)
		{
			return ((WallObject) object).getConvexHull();
		}
		if (object instanceof GroundObject)
		{
			return ((GroundObject) object).getConvexHull();
		}
		if (object instanceof DecorativeObject)
		{
			return ((DecorativeObject) object).getConvexHull();
		}
		return null;
	}
}

