	/** UI commands enqueue the complete mutation, including saved configuration, on the client thread. */
	private void onClient(Runnable action)
	{
		long expected = lifecycle;
		clientThread.invoke(() ->
		{
			if (enabled && lifecycle == expected)
			{
				action.run();
			}
		});
	}

