	private static void add(List<Alternative> choices, Skill skill, int level, boolean members, Quest quest, int... ids)
	{
		for (int id : ids)
		{
			choices.add(new Alternative(id, members, quest, new SkillReq(skill, level)));
		}
	}
}

package com.levelinghelper.data;

import com.levelinghelper.model.TrainingMethod;
import com.levelinghelper.model.TrainingStyle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class TrainingCatalog
{
	private static final List<TrainingMethod> ALL = build();

	private TrainingCatalog()
	{
	}

	public static List<TrainingMethod> all()
	{
		return ALL;
	}

	public static TrainingMethod byId(String id)
	{
		if (id == null)
		{
			return null;
		}
		for (TrainingMethod method : ALL)
		{
			if (method.id().equals(id))
			{
				return method;
			}
			TrainingMethod banking = method.forStyle(TrainingStyle.PROFIT);
			if (banking.id().equals(id))
			{
				return banking;
			}
		}
		return null;
	}

	private static List<TrainingMethod> build()
	{
		List<TrainingMethod> all = new ArrayList<TrainingMethod>();
		CombatMethods.register(all);
		GatheringMethods.register(all);
		ProductionMethods.register(all);
		SupportMethods.register(all);
		all.replaceAll(RoutePreparation::review);
		return Collections.unmodifiableList(all);
	}
}

package com.levelinghelper.guide;

import java.awt.Polygon;
import java.awt.Rectangle;

public final class DirectionArrow
{
	private DirectionArrow()
	{
	}

	/** Clamp a minimap direction marker inside the circular map. Yaw uses 14-bit Jagex units. */
	public static Polygon polygon(double dx, double dy, int yaw, Rectangle minimap)
	{
		if (dx == 0 && dy == 0 || minimap.width < 32 || minimap.height < 32)
		{
			return null;
		}
		double angle = (yaw & 0x3fff) * Math.PI * 2 / 16384.0;
		double x = dx * Math.cos(angle) + dy * Math.sin(angle);
		double y = dx * Math.sin(angle) - dy * Math.cos(angle);
		double length = Math.hypot(x, y);
		double ux = x / length;
		double uy = y / length;
		double radius = Math.min(minimap.width, minimap.height) / 2.0 - 12;
		double reach = Math.min(length, radius);
		double cx = minimap.getCenterX() + ux * reach;
		double cy = minimap.getCenterY() + uy * reach;
		// Shaft and arrowhead, facing the destination. The black outline is added by the overlay.
		int[] along = {-7, 0, 0, 8, 0, 0, -7};
		int[] across = {-3, -3, -7, 0, 7, 3, 3};
		Polygon arrow = new Polygon();
		for (int i = 0; i < along.length; i++)
		{
			arrow.addPoint((int) Math.round(cx + ux * along[i] - uy * across[i]),
				(int) Math.round(cy + uy * along[i] + ux * across[i]));
		}
		return arrow;
	}
}

package com.levelinghelper.guide;

import com.levelinghelper.model.GuideStep;
import com.levelinghelper.model.StepKind;
import com.levelinghelper.model.TrainingMethod;
import net.runelite.api.coords.WorldPoint;

public final class GuideController
{
	private TrainingMethod method;
	private int stepIndex;
	private boolean armed;
	private GuideTick lastTick;

	public void start(TrainingMethod method)
	{
		this.method = method;
		this.stepIndex = 0;
		this.armed = false;
		this.lastTick = null;
	}

	public void stop()
	{
		method = null;
		stepIndex = 0;
		armed = false;
		lastTick = null;
	}

	public boolean running()
	{
		return method != null;
	}

	public TrainingMethod method()
	{
		return method;
	}

	public int stepIndex()
	{
		return stepIndex;
	}

	public GuideStep current()
	{
		if (method == null || method.steps().isEmpty())
		{
			return null;
		}
		return method.steps().get(stepIndex);
	}

	public boolean tick(GuideTick tick, boolean autoAdvance, int defaultRadius)
	{
		observe(tick);
		if (method == null || !autoAdvance)
		{
			return false;
		}
		GuideStep step = current();
		if (step == null)
		{
			return false;
		}
		if (!shouldAdvance(step, tick, defaultRadius))
		{
			return false;
		}
		advance();
		return true;
	}

	/** Observe completion prerequisites even when automatic progression is disabled. */
	public void observe(GuideTick tick)
	{
		lastTick = tick;
		GuideStep step = current();
		if (step == null)
		{
			return;
		}
		switch (step.advance())
		{
			case BANK_CLOSED:
				armed |= tick.bankOpen();
				break;
			case INVENTORY_HAS_SPACE:
			case NEAR_AND_EMPTIED:
				armed |= tick.inventoryFull();
				break;
			case ITEM_GONE:
				armed |= tick.inventoryKnown() && !tick.watchedItemGone();
				break;
			default:
				break;
		}
	}

	public void advance()
	{
		if (method == null || method.steps().isEmpty())
		{
			return;
		}
		armed = false;
		int next = stepIndex + 1;
		if (next >= method.steps().size())
		{
			next = Math.max(0, Math.min(method.loopFrom(), method.steps().size() - 1));
		}
		stepIndex = next;
		// The full inventory that completed training also arms the following drop/hopper step.
		if (lastTick != null && lastTick.inventoryFull()
			&& (current().advance() == com.levelinghelper.model.AdvanceWhen.INVENTORY_HAS_SPACE
				|| current().advance() == com.levelinghelper.model.AdvanceWhen.NEAR_AND_EMPTIED))
		{
			armed = true;
		}
	}

	public void back()
	{
		if (method == null)
		{
			return;
		}
		armed = false;
		if (stepIndex > 0)
		{
			stepIndex--;
		}
	}

	public void jumpToBank()
	{
		if (method == null)
		{
			return;
		}
		for (int i = 0; i < method.steps().size(); i++)
		{
			if (method.steps().get(i).kind() == StepKind.BANK)
			{
				stepIndex = i;
				armed = false;
				return;
			}
		}
	}

	private boolean shouldAdvance(GuideStep step, GuideTick tick, int defaultRadius)
	{
		switch (step.advance())
		{
			case NEAR_TARGET:
				return near(tick.player(), step.target(), step.arrivalRadius(defaultRadius));
			case BANK_CLOSED:
				if (tick.bankOpen())
				{
					armed = true;
					return false;
				}
				return armed && tick.prepared() && tick.inventoryKnown();
			case INVENTORY_FULL:
				return tick.inventoryFull();
			case INVENTORY_HAS_SPACE:
				if (!tick.inventoryKnown())
				{
					return false;
				}
				if (tick.inventoryFull())
				{
					armed = true;
					return false;
				}
				return armed;
			case NEAR_AND_EMPTIED:
				if (tick.inventoryFull())
				{
					armed = true;
				}
				return armed
					&& tick.inventoryKnown()
					&& !tick.inventoryFull()
					&& near(tick.player(), step.target(), step.arrivalRadius(defaultRadius));
			case ITEM_GONE:
				return armed && tick.inventoryKnown() && tick.watchedItemGone();
			case HIGHLIGHT_VISIBLE:
				return tick.highlightVisible();
			case MANUAL:
			default:
				return false;
		}
	}

	static boolean near(WorldPoint player, WorldPoint target, int radius)
	{
		if (player == null || target == null)
		{
			return false;
		}
		if (player.getPlane() != target.getPlane())
		{
			return false;
		}
		int dx = Math.abs(player.getX() - target.getX());
		int dy = Math.abs(player.getY() - target.getY());
		return Math.max(dx, dy) <= radius;
	}
}

