import static org.junit.Assert.*;

public class CatalogCoverageTest
{
	private LevelLookup profile(int level, AccountMode mode)
	{
		return new LevelLookup()
		{
			public int level(Skill skill) { return level; }
			public int combatLevel() { return 126; }
			public boolean questComplete(Quest quest) { return true; }
			public boolean allowWilderness() { return true; }
			public boolean membersWorld() { return mode == AccountMode.P2P; }
		};
	}

	@Test
	public void everyCatalogRouteHasExplicitPreparationAndInventoryPolicy()
	{
		assertEquals(197, TrainingCatalog.all().size());
		assertEquals(24, TrainingCatalog.all().stream().map(TrainingMethod::skill).distinct().count());
		for (TrainingMethod method : TrainingCatalog.all())
		{
			assertTrue(method.id(), method.preparationReviewed());
			assertNotNull(method.id(), method.resourceHandling());
			assertTrue(method.id(), method.preparationFreeSlots() >= 0);
			List<ItemRequirement> inputs = method.resolvedItems(profile(method.minLevel(), AccountMode.P2P));
			assertTrue(method.id(), !inputs.isEmpty() || !method.noItemsReason().isEmpty());
			if (inputs.stream().noneMatch(item -> !item.optional()))
			{
				assertTrue(method.id(), !method.manualChecks().isEmpty() || !method.noItemsReason().isEmpty());
			}
			for (ItemRequirement item : inputs)
			{
				assertFalse(method.id() + item.label(), item.source().isEmpty());
				assertTrue(method.id(), item.quantity() > 0);
			}
			for (TrainingStyle style : TrainingStyle.values())
			{
				TrainingMethod variant = method.forStyle(style);
				assertTrue(variant.id(), variant.preparationReviewed());
				assertEquals(method.manualChecks(), variant.manualChecks());
				assertTrue(variant.id(), variant.loopFrom() >= 0 && variant.loopFrom() < variant.steps().size());
				if (style == TrainingStyle.PROFIT)
				{
					assertFalse(variant.id(), variant.steps().stream().anyMatch(step -> step.kind() == StepKind.DROP));
					assertFalse(variant.id(), variant.steps().stream().anyMatch(step -> step.instruction().toLowerCase().matches(".*\\bdrop (?:the |your |leftover )?(?:ore|fish|resources|inventory)\\b.*")));
				}
				if (variant.resourceHandling() == ResourceHandling.BANK)
				{
					assertEquals(variant.id(), StepKind.BANK, variant.steps().get(variant.loopFrom()).kind());
					assertTrue(variant.id(), variant.preparationFreeSlots() > 0);
					assertTrue(variant.id(), variant.steps().stream().anyMatch(step -> step.kind() == StepKind.TRAIN && step.advance() == AdvanceWhen.INVENTORY_FULL));
				}
			}
		}
	}

	@Test
	public void everySkillModeStyleAndLevelPreservesEligibilityAndBanking()
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL) continue;
			for (AccountMode mode : AccountMode.values()) for (TrainingStyle style : TrainingStyle.values()) for (int level = 1; level <= 99; level++)
			{
				LevelLookup lookup = profile(level, mode);
				TrainingMethod selected = MethodSelector.select(TrainingCatalog.all(), skill, mode, style, level, lookup);
				List<TrainingMethod> alternatives = MethodSelector.alternatives(TrainingCatalog.all(), skill, mode, style, level, lookup);
				if (selected != null) assertTrue(selected.id(), alternatives.contains(selected));
				for (TrainingMethod method : alternatives)
				{
					assertEquals(method.id(), skill, method.skill());
					assertTrue(method.id(), method.modes().contains(mode));
					assertTrue(method.id(), method.containsLevel(level));
					assertTrue(method.id(), method.requirementsMet(lookup));
					assertFalse(method.id(), mode == AccountMode.F2P && method.skill().isMembers());
					if (style == TrainingStyle.PROFIT) assertFalse(method.id(), method.steps().stream().anyMatch(step -> step.kind() == StepKind.DROP));
				}
			}
		}
	}

	@Test
	public void noDeclaredRequiredInputIsInventedFromAnEmptyInventoryOrUnknownBank()
	{
		SupplyTracker tracker = new SupplyTracker();
		for (TrainingMethod method : TrainingCatalog.all()) for (TrainingStyle style : TrainingStyle.values())
		{
			for (SupplyTracker.Stock stock : tracker.check(method.forStyle(style), SupplyTrackerTest.container(), SupplyTrackerTest.container(), profile(99, AccountMode.P2P), true))
			{
				assertFalse(method.id() + stock.requirement.label(), stock.ready());
				assertFalse(method.id(), stock.bankKnown);
				assertFalse(method.id(), stock.absentFromBank());
			}
		}
	}

	@Test
	public void fullInventoryBankLoopsWaitForSpaceAndReturnToTheSelectedRoute()
	{
		for (TrainingMethod source : TrainingCatalog.all()) for (TrainingStyle style : TrainingStyle.values())
		{
			TrainingMethod method = source.forStyle(style);
			if (method.resourceHandling() != ResourceHandling.BANK) continue;
			GuideController controller = new GuideController();
			controller.start(method);
			while (controller.current().kind() != StepKind.TRAIN) controller.advance();
			controller.tick(new GuideTick(null, false, true, false, false, true, true), true, 10);
			assertEquals(method.id(), StepKind.BANK, controller.current().kind());
			controller.tick(new GuideTick(null, true, true, false, false, false, true), true, 10);
			controller.tick(new GuideTick(null, false, true, false, false, false, true), true, 10);
			assertEquals(method.id(), StepKind.BANK, controller.current().kind());
			assertTrue(method.id(), controller.tick(new GuideTick(null, false, false, false, false, true, true), true, 10));
			assertSame(method, controller.method());
			assertNotEquals(method.id(), StepKind.BANK, controller.current().kind());
		}
	}

	@Test
	public void writeRouteMatrix() throws Exception
	{
		List<String> rows = new ArrayList<>();
		rows.add("skill\tname\tmodes\tlevels\titems\tmanual checks\thandling\tsteps");
		for (TrainingMethod method : TrainingCatalog.all())
		{
			rows.add(method.skill() + "\t" + method.name() + "\t" + method.modes() + "\t" + method.minLevel() + "-" + method.maxLevel()
				+ "\t" + method.resolvedItems(profile(method.minLevel(), AccountMode.P2P)).stream()
					.map(item -> item.label() + (item.optional() ? " (optional)" : item.departureOnly() ? " (first trip)" : ""))
					.collect(Collectors.joining("; "))
				+ "\t" + String.join("; ", method.manualChecks()) + "\t" + method.resourceHandling()
				+ "\t" + method.steps().stream().map(step -> step.kind() + ":" + step.advance()).collect(Collectors.joining("; ")));
		}
		Files.createDirectories(Path.of("build/reports"));
		Files.write(Path.of("build/reports/catalog-coverage.tsv"), rows);
	}
}

package com.levelinghelper;

import com.levelinghelper.data.TrainingCatalog;
import com.levelinghelper.guide.*;
import com.levelinghelper.model.*;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import net.runelite.api.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CatalogRequirementsTest
{
	private static final class Profile implements LevelLookup
	{
		final EnumSet<Quest> quests = EnumSet.noneOf(Quest.class);
		boolean wilderness;
		public int level(Skill skill) { return 99; }
		public int combatLevel() { return 126; }
		public boolean questComplete(Quest quest) { return quests.contains(quest); }
		public boolean allowWilderness() { return wilderness; }
	}

	private TrainingMethod select(Skill skill, TrainingStyle style, int level, Profile profile)
	{
		return MethodSelector.select(TrainingCatalog.all(), skill, AccountMode.P2P, style, level, profile);
	}

	@Test
	public void questLockedMagicFallsBackAndIceBurstRequiresLevel70()
	{
		Profile profile = new Profile();
		assertEquals("Combat spells", select(Skill.MAGIC, TrainingStyle.FAST, 70, profile).name());
		profile.quests.add(Quest.DESERT_TREASURE_I);
		assertEquals("Combat spells", select(Skill.MAGIC, TrainingStyle.FAST, 69, profile).name());
		assertEquals("Ice Burst", select(Skill.MAGIC, TrainingStyle.FAST, 70, profile).name());
		TrainingMethod burst = select(Skill.MAGIC, TrainingStyle.FAST, 70, profile);
		ItemRequirement mask = burst.items().get(0);
		assertTrue(mask.equipped());
		assertTrue(mask.met(id -> id == ItemID.FACEMASK ? 1 : 0));
		assertTrue(mask.met(id -> id == ItemID.ARAXYTE_SLAYER_HELMET_I_29822 ? 1 : 0));
		assertFalse(mask.met(id -> id == ItemID.BLACK_MASK ? 1 : 0));
	}

	@Test
	public void wildernessNeedsExplicitOptInAcrossEveryAffectedSkill()
	{
		Profile profile = new Profile();
		for (Skill skill : new Skill[]{Skill.PRAYER, Skill.HUNTER, Skill.AGILITY})
		{
			TrainingMethod method = select(skill, TrainingStyle.FAST, 60, profile);
			assertNotNull(method);
			assertNotEquals(RouteRisk.WILDERNESS, method.risk());
		}
		profile.wilderness = true;
		assertEquals("Chaos altar", select(Skill.PRAYER, TrainingStyle.FAST, 60, profile).name());
		assertEquals("Wilderness course", select(Skill.AGILITY, TrainingStyle.FAST, 60, profile).name());
		assertEquals("Black chinchompas", select(Skill.HUNTER, TrainingStyle.FAST, 80, profile).name());
	}

	@Test
	public void resourceTargetsDistinguishOreTypesAndDepletedRocks()
	{
		GuideStep iron = select(Skill.MINING, TrainingStyle.FAST, 20, new Profile()).steps().get(2);
		assertTrue(iron.matchesObject(ObjectID.IRON_ROCKS, "Rocks"));
		assertFalse(iron.matchesObject(ObjectID.COPPER_ROCKS_11161, "Rocks"));
		assertFalse(iron.matchesObject(ObjectID.ROCKS_11390, "Rocks"));
		assertFalse(iron.matchesNpc(1, "Rocks"));
	}

	@Test
	public void anglerfishUseTheActualNpcAndBarbarianFishingRequiresBait()
	{
		Profile profile = new Profile();
		TrainingMethod angler = select(Skill.FISHING, TrainingStyle.PROFIT, 82, profile);
		assertEquals("Anglerfish", angler.name());
		assertTrue(angler.summary().contains("Port Piscarilius"));
		assertTrue(angler.steps().get(2).matchesNpc(6825, "Rod Fishing spot"));
		assertFalse(angler.steps().get(2).matchesNpc(1510, "Fishing spot"));
		TrainingMethod barb = select(Skill.FISHING, TrainingStyle.BALANCED, 48, profile);
		assertEquals("Barbarian fishing", barb.name());
		assertTrue(barb.items().stream().anyMatch(item -> item.met(id -> id == ItemID.FEATHER ? 100 : 0)));
	}

	@Test
	public void unlockedProfilesCoverAllStylesAndLevelsWithRealisticPrimaryLevels()
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL) continue;
			for (int level = 1; level <= 99; level++)
			{
				final int primaryLevel = level;
				LevelLookup profile = new LevelLookup()
				{
					public int level(Skill queried) { return queried == skill ? primaryLevel : 99; }
					public int combatLevel() { return 126; }
					public boolean questComplete(Quest quest) { return true; }
				};
				for (TrainingStyle style : TrainingStyle.values())
				{
					TrainingMethod method = MethodSelector.select(TrainingCatalog.all(), skill, AccountMode.P2P, style, level, profile);
					// Quest rewards make some pre-unlock levels unattainable on an unlocked account.
					if (skill == Skill.HERBLORE && level < 3 || skill == Skill.SAILING && level < 2) continue;
					assertNotNull(skill + " " + style + " " + level, method);
					assertTrue(method.requirementsMet(profile));
				}
			}
		}
	}

	@Test
	public void targetNamesAreLocaleIndependentAndCatalogSetsCannotBeMutated()
	{
		Locale previous = Locale.getDefault();
		try
		{
			Locale.setDefault(Locale.forLanguageTag("tr-TR"));
			GuideStep step = GuideSteps.roam("Fish", AdvanceWhen.MANUAL, "FISHING SPOT");
			assertTrue(step.matchesNpc(1, "Fishing spot"));
		}
		finally { Locale.setDefault(previous); }
		TrainingMethod method = TrainingCatalog.all().get(0);
		method.modes().clear();
		assertFalse(method.modes().isEmpty());
	}
}

package com.levelinghelper;

import com.levelinghelper.guide.DirectionArrow;
import java.awt.Polygon;
import java.awt.Rectangle;
import org.junit.Test;
import static org.junit.Assert.*;

public class DirectionArrowTest
{
	private final Rectangle viewport = new Rectangle(20, 40, 800, 500);

	@Test
	public void arrowRotatesWithTheCameraInAllFourCardinalDirections()
	{
		Polygon north = DirectionArrow.polygon(0, 100, 0, viewport);
		Polygon east = DirectionArrow.polygon(0, 100, 4096, viewport);
		Polygon south = DirectionArrow.polygon(0, 100, 8192, viewport);
		Polygon west = DirectionArrow.polygon(0, 100, 12288, viewport);
		assertTrue(north.ypoints[0] < viewport.getCenterY());
		assertTrue(east.xpoints[0] > viewport.getCenterX());
		assertTrue(south.ypoints[0] > viewport.getCenterY());
		assertTrue(west.xpoints[0] < viewport.getCenterX());
		for (Polygon arrow : new Polygon[]{north, east, south, west})
		{
			for (int i = 0; i < arrow.npoints; i++) assertTrue(viewport.contains(arrow.xpoints[i], arrow.ypoints[i]));
		}
	}

	@Test
	public void degenerateAndSmallViewportsDoNotProduceOffscreenArrows()
	{
		assertNull(DirectionArrow.polygon(0, 0, 0, viewport));
		assertNull(DirectionArrow.polygon(1, 0, 0, new Rectangle(10, 10)));
		Rectangle small = new Rectangle(20, 30, 40, 40);
		Polygon arrow = DirectionArrow.polygon(-100, 100, 0, small);
		for (int i = 0; i < arrow.npoints; i++) assertTrue(small.contains(arrow.xpoints[i], arrow.ypoints[i]));
	}
}

package com.levelinghelper;

import com.levelinghelper.data.TrainingCatalog;
import com.levelinghelper.guide.LevelLookup;
import com.levelinghelper.model.*;
import java.util.*;
import net.runelite.api.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class GlobalSupplyTest
{
	private final SupplyTracker tracker = new SupplyTracker();
	private final Map<Integer, Integer> inventory = new HashMap<>();
	private final Map<Integer, Integer> worn = new HashMap<>();
	private final Map<Integer, Integer> stored = new HashMap<>();
	private final LevelLookup lookup = new LevelLookup()
	{
		public int level(Skill skill) { return 99; }
		public int combatLevel() { return 126; }
		public boolean membersWorld() { return true; }
		public boolean matches(ItemCategory category, int id) { return category == ItemCategory.SELF_AMMO_WEAPON && id == ItemID.MITHRIL_DART || category == ItemCategory.RANGED_WEAPON && id == ItemID.MITHRIL_DART; }
		public int itemCount(int id) { return inventory.getOrDefault(id, 0); }
		public int equippedCount(int id) { return worn.getOrDefault(id, 0); }
		public int storedItemCount(int id) { return stored.getOrDefault(id, 0); }
	};

	private TrainingMethod method(Skill skill, String name)
	{
		return TrainingCatalog.all().stream().filter(method -> method.skill() == skill && method.name().equals(name)).findFirst().get();
	}

	private net.runelite.api.ItemContainer container(Map<Integer, Integer> stock)
	{
		return SupplyTrackerTest.container(stock.entrySet().stream().map(entry -> new Item(entry.getKey(), entry.getValue())).toArray(Item[]::new));
	}

	private List<SupplyTracker.Stock> stock(TrainingMethod method)
	{
		return tracker.check(method, container(inventory), container(worn), lookup, true);
	}

	private SupplyTracker.Stock row(TrainingMethod method, String contains)
	{
		return stock(method).stream().filter(item -> item.requirement.label().contains(contains)).findFirst().get();
	}

	@Test
	public void elementalStaffIsRecognizedEquippedCarriedAndInTheObservedBank()
	{
		TrainingMethod fire = method(Skill.MAGIC, "Fire Strike");
		inventory.put(ItemID.AIR_RUNE, 100); inventory.put(ItemID.MIND_RUNE, 100);
		worn.put(ItemID.STAFF_OF_FIRE, 1);
		SupplyTracker.Stock element = row(fire, "Fire runes");
		assertTrue(element.ready()); assertTrue(element.supplied); assertEquals(ItemID.STAFF_OF_FIRE, element.presentId);
		worn.clear(); inventory.put(ItemID.STAFF_OF_FIRE, 1);
		element = row(fire, "Fire runes");
		assertFalse(element.ready()); assertTrue(element.needsEquipping()); assertEquals(ItemID.STAFF_OF_FIRE, element.carriedProvider);
		inventory.remove(ItemID.STAFF_OF_FIRE);
		tracker.bind("Caster"); tracker.observeBank(SupplyTrackerTest.container(new Item(ItemID.STAFF_OF_FIRE, 1)));
		element = row(fire, "Fire runes");
		assertTrue(element.canWithdraw()); assertFalse(element.absentFromBank()); assertEquals(ItemID.STAFF_OF_FIRE, element.bankProvider);
	}

	@Test
	public void spellRecommendationsPreferACompleteCastThePlayerAlreadyHas()
	{
		inventory.put(ItemID.AIR_RUNE, 100); inventory.put(ItemID.FIRE_RUNE, 100); inventory.put(ItemID.MIND_RUNE, 100);
		TrainingMethod combat = method(Skill.MAGIC, "Combat spells");
		assertTrue(stock(combat).stream().filter(item -> !item.requirement.optional()).allMatch(SupplyTracker.Stock::ready));
		assertTrue(combat.resolvedItems(lookup).stream().anyMatch(item -> item.label().startsWith("Fire Strike:")));
		assertFalse(combat.resolvedItems(lookup).stream().anyMatch(item -> item.label().contains("Death")));
	}

	@Test
	public void equippedThrownWeaponsDoNotRequireSeparateArrows()
	{
		TrainingMethod ranged = TrainingCatalog.all().stream().filter(method -> method.skill() == Skill.RANGED).findFirst().get();
		worn.put(ItemID.MITHRIL_DART, 100);
		assertTrue(row(ranged, "Compatible ammunition").ready());
		worn.clear(); inventory.put(ItemID.MITHRIL_DART, 100);
		assertTrue(row(ranged, "Compatible ammunition").needsEquipping());
		inventory.clear();
		assertFalse(row(ranged, "Compatible ammunition").ready());
	}

	@Test
	public void exactConstructionActionQuantitiesAndStoredFarmingToolsAreDetected()
	{
		TrainingMethod larders = method(Skill.CONSTRUCTION, "Oak larders");
		inventory.put(ItemID.OAK_PLANK, 7);
		assertFalse(row(larders, "Oak planks").ready());
		inventory.put(ItemID.OAK_PLANK, 8);
		assertTrue(row(larders, "Oak planks").ready());
		TrainingMethod farming = method(Skill.FARMING, "Allotments");
		stored.put(ItemID.SPADE, 1);
		SupplyTracker.Stock spade = row(farming, "Spade");
		assertFalse(spade.ready()); assertTrue(spade.canRetrieve()); assertFalse(spade.absentFromBank());
		inventory.put(ItemID.SPADE, 1);
		assertTrue(row(farming, "Spade").ready());
	}

	@Test
	public void altarTiaraReplacesTalismanAndMagicImbueReplacesEarthTalismanOnlyWhileActive()
	{
		TrainingMethod lava = method(Skill.RUNECRAFT, "Lava runes");
		worn.put(ItemID.FIRE_TIARA, 1);
		assertTrue(row(lava, "Fire altar access").ready());
		assertFalse(row(lava, "Earth talisman or Magic Imbue").ready());
		LevelLookup imbue = new LevelLookup()
		{
			public int level(Skill skill) { return 99; }
			public int combatLevel() { return 126; }
			public int varbit(int id) { return id == net.runelite.api.gameval.VarbitID.MAGIC_IMBUE_ACTIVE ? 1 : 0; }
		};
		assertTrue(tracker.check(lava, container(inventory), container(worn), imbue, true).stream()
			.filter(item -> item.requirement.label().equals("Earth talisman or Magic Imbue")).findFirst().get().ready());
	}
	@Test
	public void poweredStaffDoesNotReplaceNamedSpellRunesOrItsRequiredSpellbook()
	{
		LevelLookup powered = new LevelLookup()
		{
			public int level(Skill skill) { return 99; }
			public int combatLevel() { return 126; }
			public boolean equippedMatches(ItemCategory category) { return category == ItemCategory.POWERED_STAFF; }
			public int varbit(int id) { return id == net.runelite.api.gameval.VarbitID.SPELLBOOK ? 1 : 0; }
		};
		assertTrue(method(Skill.MAGIC, "Combat spells").resolvedItems(powered).stream().anyMatch(item -> item.label().equals("Charged powered staff")));
		assertTrue(method(Skill.MAGIC, "Combat spells").setupIssues(powered).isEmpty());
		assertFalse(method(Skill.MAGIC, "High Alchemy").setupIssues(powered).isEmpty());
		assertFalse(method(Skill.MAGIC, "Curse splash").setupIssues(powered).isEmpty());
		assertTrue(method(Skill.MAGIC, "Fire Strike").resolvedItems(powered).stream().anyMatch(item -> item.label().startsWith("Fire Strike:")));
	}

}

package com.levelinghelper;

import com.levelinghelper.guide.*;
import com.levelinghelper.model.*;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class GuideControllerRegressionTest
{
	private final WorldPoint at = new WorldPoint(100, 100, 0);

	private GuideController guide(GuideStep... steps)
	{
		List<TrainingMethod> methods = new ArrayList<>();
		TrainingMethod.Builder builder = TrainingMethod.builder(methods, Skill.MINING, "Regression")
			.summary("Exercise the route state machine");
		for (GuideStep step : steps) builder.step(step);
		builder.save();
		GuideController controller = new GuideController();
		controller.start(methods.get(0));
		return controller;
	}

	private GuideTick tick(boolean bank, boolean full, boolean gone, boolean prepared)
	{
		return new GuideTick(at, bank, full, gone, false, prepared);
	}

	@Test
	public void droppingBeforeTheFollowingTickDoesNotStall()
	{
		GuideController controller = guide(GuideSteps.train("Mine", at, AdvanceWhen.INVENTORY_FULL), GuideSteps.drop("Drop"));
		assertTrue(controller.tick(tick(false, true, false, true), true, 10));
		assertEquals(1, controller.stepIndex());
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
		assertEquals(0, controller.stepIndex());
	}

	@Test
	public void hopperRemembersFullInventoryWhenItIsEmptiedBeforeTheNextTick()
	{
		GuideController controller = guide(GuideSteps.train("Mine", at, AdvanceWhen.INVENTORY_FULL), GuideSteps.hopper("Deposit", at));
		controller.tick(tick(false, true, false, true), true, 10);
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
	}

	@Test
	public void bankRequiresAnObservedOpenAndTheRequiredSupplies()
	{
		GuideController controller = guide(GuideSteps.bank("Withdraw", at), GuideSteps.note("Ready"));
		assertFalse(controller.tick(tick(false, false, false, true), true, 10));
		assertFalse(controller.tick(tick(true, false, false, false), true, 10));
		assertFalse(controller.tick(tick(false, false, false, false), true, 10));
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
	}

	@Test
	public void missingMaterialsAreNotMistakenForACompletedInventory()
	{
		GuideController controller = guide(GuideSteps.untilEmpty("Process", at, "Grapes"), GuideSteps.note("Finished"));
		assertFalse(controller.tick(tick(false, false, true, true), true, 10));
		controller.observe(tick(false, false, false, true));
		assertTrue(controller.tick(tick(false, false, true, true), true, 10));
	}

	@Test
	public void manualPauseStillObservesBankStateAndBackClearsTheLatch()
	{
		GuideController controller = guide(GuideSteps.bank("Bank", at), GuideSteps.note("Ready"));
		assertFalse(controller.tick(tick(true, false, false, true), false, 10));
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
		controller.back();
		assertFalse(controller.tick(tick(false, false, false, true), true, 10));
	}

	@Test
	public void arrivalSettingCapsTheRouteRadiusAndHonorsThePlane()
	{
		GuideController controller = guide(GuideSteps.travel("Walk", at, 18), GuideSteps.note("Arrived"));
		assertFalse(controller.tick(new GuideTick(at.dx(8), false, false, false, false), true, 3));
		assertFalse(controller.tick(new GuideTick(at.dz(1), false, false, false, false), true, 3));
		assertTrue(controller.tick(new GuideTick(at.dx(2), false, false, false, false), true, 3));
	}

	@Test
	public void unavailableInventoryCannotArmMaterialCompletionOrFinishDropping()
	{
		GuideController controller = guide(GuideSteps.untilEmpty("Process", at, "Grapes"), GuideSteps.note("Finished"));
		assertFalse(controller.tick(new GuideTick(at, false, false, false, false, true, false), true, 10));
		assertFalse(controller.tick(tick(false, false, true, true), true, 10));
		controller = guide(GuideSteps.train("Mine", at, AdvanceWhen.INVENTORY_FULL), GuideSteps.drop("Drop"));
		controller.tick(tick(false, true, false, true), true, 10);
		assertFalse(controller.tick(new GuideTick(at, false, false, false, false, true, false), true, 10));
		assertTrue(controller.tick(tick(false, false, false, true), true, 10));
	}
}

package com.levelinghelper;

import com.levelinghelper.data.TrainingCatalog;
import com.levelinghelper.guide.GuideController;
import com.levelinghelper.guide.GuideSteps;
import com.levelinghelper.guide.GuideTick;
import com.levelinghelper.guide.LevelLookup;
import com.levelinghelper.guide.MethodSelector;
import com.levelinghelper.guide.TrainingMath;
import com.levelinghelper.model.AccountMode;
import com.levelinghelper.model.AdvanceWhen;
import com.levelinghelper.model.TrainingMethod;
import com.levelinghelper.model.TrainingStyle;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Skill;
import net.runelite.api.Quest;
import net.runelite.api.coords.WorldPoint;
import org.junit.Assert;
import org.junit.Test;

public class GuideLogicTest
{
	@Test
	public void xpTableAndCombatLevel()
	{
		Assert.assertEquals(83, TrainingMath.xpBetween(0, 2));
		Assert.assertEquals(0, TrainingMath.xpBetween(13034431, 99));
		Assert.assertEquals(5, TrainingMath.actions(101, 25));
		Assert.assertEquals(0, TrainingMath.actions(0, 25));
		Assert.assertEquals(-1, TrainingMath.actions(10, 0));
		Assert.assertEquals(3_600_000L, TrainingMath.millis(10000, 10000));
		Assert.assertEquals("1h 0m", TrainingMath.duration(3_600_000L));
		Assert.assertEquals("done", TrainingMath.duration(0));
		Assert.assertEquals(3, TrainingMath.combatLevel(1, 1, 1, 10, 1, 1, 1));
	}

	@Test
	public void directionUsesNorthAndEast()
	{
		Assert.assertEquals("5 tiles northeast", TrainingMath.direction(new WorldPoint(0, 0, 0), new WorldPoint(5, 5, 0)));
		Assert.assertEquals("on another floor", TrainingMath.direction(new WorldPoint(0, 0, 0), new WorldPoint(1, 1, 1)));
	}

	@Test
	public void stepsAdvanceOnceAndLoop()
	{
		List<TrainingMethod> methods = new ArrayList<TrainingMethod>();
		TrainingMethod.builder(methods, Skill.WOODCUTTING, "Loop")
			.summary("A test training loop")
			.levels(1, 99)
			.modes(AccountMode.F2P)
			.styles(TrainingStyle.BALANCED)
			.loop(1)
			.step(GuideSteps.bank("bank", new WorldPoint(0, 0, 0)))
			.step(GuideSteps.travel("walk", new WorldPoint(10, 0, 0), 5))
			.step(GuideSteps.train("chop", new WorldPoint(10, 0, 0), AdvanceWhen.INVENTORY_FULL, "Willow"))
			.step(GuideSteps.drop("drop"))
			.save();
		GuideController controller = new GuideController();
		controller.start(methods.get(0));

		Assert.assertFalse(controller.tick(tick(new WorldPoint(100, 0, 0), false, false), true, 8));
		Assert.assertEquals(0, controller.stepIndex());

		Assert.assertFalse(controller.tick(tick(new WorldPoint(0, 0, 0), true, false), true, 8));
		Assert.assertEquals(0, controller.stepIndex());
		Assert.assertTrue(controller.tick(tick(new WorldPoint(0, 0, 0), false, false), true, 8));
		Assert.assertEquals(1, controller.stepIndex());

		Assert.assertFalse(controller.tick(tick(new WorldPoint(10, 0, 1), false, false), true, 8));
		Assert.assertTrue(controller.tick(tick(new WorldPoint(12, 0, 0), false, false), true, 8));
		Assert.assertEquals(2, controller.stepIndex());

		Assert.assertFalse(controller.tick(tick(new WorldPoint(10, 0, 0), false, false), true, 8));
		Assert.assertTrue(controller.tick(tick(new WorldPoint(10, 0, 0), false, true), true, 8));
		Assert.assertEquals(3, controller.stepIndex());

		Assert.assertFalse(controller.tick(tick(new WorldPoint(10, 0, 0), false, true), true, 8));
		Assert.assertTrue(controller.tick(tick(new WorldPoint(10, 0, 0), false, false), true, 8));
		Assert.assertEquals(1, controller.stepIndex());

		controller.start(methods.get(0));
		Assert.assertFalse(controller.tick(tick(new WorldPoint(0, 0, 0), false, false), false, 8));
		Assert.assertEquals(0, controller.stepIndex());
	}

	@Test
	public void catalogCoversEveryLevel()
	{
		Set<String> ids = new HashSet<String>();
		for (TrainingMethod method : TrainingCatalog.all())
		{
			Assert.assertTrue(ids.add(method.id()));
			Assert.assertFalse(method.steps().isEmpty());
			Assert.assertTrue(method.maxLevel() >= method.minLevel());
			Assert.assertTrue(method.maxLevel() <= 99);
			Assert.assertTrue(method.minLevel() >= 1);
			Assert.assertTrue(method.xpPerHour() > 0);
			Assert.assertTrue(method.loopFrom() >= 0 && method.loopFrom() < method.steps().size());
			Assert.assertFalse(method.summary().isEmpty());
			if (method.skill().isMembers())
			{
				Assert.assertFalse(method.modes().contains(AccountMode.F2P));
			}
		}

		for (Skill skill : Skill.values())
		{
			if ("Overall".equals(skill.getName()))
			{
				continue;
			}
			for (int level = 1; level <= 99; level++)
			{
				Assert.assertNotNull(skill.getName() + " members " + level,
					MethodSelector.select(TrainingCatalog.all(), skill, AccountMode.P2P, TrainingStyle.BALANCED, level, maxed()));
				TrainingMethod free = MethodSelector.select(TrainingCatalog.all(), skill, AccountMode.F2P, TrainingStyle.BALANCED, level, maxed());
				if (skill.isMembers())
				{
					Assert.assertNull(skill.getName(), free);
				}
				else
				{
					Assert.assertNotNull(skill.getName() + " free " + level, free);
				}
			}
		}
	}

	@Test
	public void selectorRespectsModeStyleAndRequirements()
	{
		Assert.assertTrue(MethodSelector.select(TrainingCatalog.all(), Skill.WOODCUTTING, AccountMode.F2P, TrainingStyle.BALANCED, 50, maxed()).name().contains("Willow"));
		Assert.assertTrue(MethodSelector.select(TrainingCatalog.all(), Skill.WOODCUTTING, AccountMode.P2P, TrainingStyle.BALANCED, 50, maxed()).name().contains("Teak"));
		Assert.assertTrue(MethodSelector.select(TrainingCatalog.all(), Skill.WOODCUTTING, AccountMode.P2P, TrainingStyle.FAST, 80, maxed()).name().contains("Teak"));
		Assert.assertEquals("Redwoods", MethodSelector.select(TrainingCatalog.all(), Skill.WOODCUTTING, AccountMode.P2P, TrainingStyle.BALANCED, 95, maxed()).name());

		Assert.assertFalse(MethodSelector.select(TrainingCatalog.all(), Skill.MAGIC, AccountMode.P2P, TrainingStyle.FAST, 70, levels(1, 3)).name().contains("Burst"));
		Assert.assertTrue(MethodSelector.select(TrainingCatalog.all(), Skill.MAGIC, AccountMode.P2P, TrainingStyle.FAST, 70, levels(99, 126)).name().contains("Burst"));

		Assert.assertEquals("Turael", MethodSelector.select(TrainingCatalog.all(), Skill.SLAYER, AccountMode.P2P, TrainingStyle.BALANCED, 20, levels(1, 3)).name());
		Assert.assertEquals("Nieve", MethodSelector.select(TrainingCatalog.all(), Skill.SLAYER, AccountMode.P2P, TrainingStyle.FAST, 40, levels(40, 90)).name());
		Assert.assertEquals("Duradel", MethodSelector.select(TrainingCatalog.all(), Skill.SLAYER, AccountMode.P2P, TrainingStyle.FAST, 60, levels(60, 110)).name());
		Assert.assertNull(MethodSelector.select(TrainingCatalog.all(), Skill.SAILING, AccountMode.F2P, TrainingStyle.BALANCED, 20, maxed()));
	}

	private static GuideTick tick(WorldPoint player, boolean bankOpen, boolean inventoryFull)
	{
		return new GuideTick(player, bankOpen, inventoryFull, false, false);
	}

	private static LevelLookup maxed()
	{
		return levels(99, 126);
	}

	private static LevelLookup levels(final int skillLevel, final int combat)
	{
		return new LevelLookup()
		{
			@Override
			public int level(Skill skill)
			{
				return skillLevel;
			}

			@Override
			public int combatLevel()
			{
				return combat;
			}

			@Override
			public boolean questComplete(Quest quest)
			{
				return true;
			}

			@Override
			public boolean allowWilderness()
			{
				return true;
			}
		};
	}
}

package com.levelinghelper;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.Mockito.*;

public class HintArrowControllerTest
{
	private Client client;
	private HintArrowController arrows;
	private final AtomicInteger type = new AtomicInteger(HintArrowType.NONE);
	private final AtomicReference<WorldPoint> point = new AtomicReference<>();
	private final AtomicReference<NPC> npc = new AtomicReference<>();
	private final WorldPoint target = new WorldPoint(100, 200, 0);

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.hasHintArrow()).thenAnswer(call -> type.get() != HintArrowType.NONE);
		when(client.getHintArrowType()).thenAnswer(call -> type.get());
		when(client.getHintArrowPoint()).thenAnswer(call -> point.get());
		when(client.getHintArrowNpc()).thenAnswer(call -> npc.get());
		doAnswer(call -> { point.set(call.getArgument(0)); type.set(HintArrowType.COORDINATE); return null; })
			.when(client).setHintArrow(any(WorldPoint.class));
		doAnswer(call -> { npc.set(call.getArgument(0)); type.set(HintArrowType.NPC); return null; })
			.when(client).setHintArrow(any(NPC.class));
		doAnswer(call -> { type.set(HintArrowType.NONE); return null; }).when(client).clearHintArrow();
		arrows = new HintArrowController(client);
	}

	@Test
	public void preservesAnExistingServerOrOtherPluginArrow()
	{
		type.set(HintArrowType.PLAYER);
		arrows.update(true, null, target);
		verify(client, never()).setHintArrow(any(WorldPoint.class));
		arrows.clear();
		verify(client, never()).clearHintArrow();
	}

	@Test
	public void neverClearsOrOverwritesAnArrowThatReplacedOurs()
	{
		arrows.update(true, null, target);
		point.set(target.dx(10));
		arrows.update(true, null, target);
		arrows.clear();
		verify(client, times(1)).setHintArrow(target);
		verify(client, never()).clearHintArrow();
	}

	@Test
	public void avoidsRewritingAnUnchangedArrowAndHonorsDisable()
	{
		arrows.update(true, null, target);
		arrows.update(true, null, target);
		verify(client, times(1)).setHintArrow(target);
		arrows.update(false, null, target);
		verify(client, times(1)).clearHintArrow();
	}

	@Test
	public void switchesOwnedTargetsAndClearsOnlyTheOwnedNpc()
	{
		NPC targetNpc = mock(NPC.class);
		arrows.update(true, null, target);
		arrows.update(true, targetNpc, null);
		verify(client).setHintArrow(targetNpc);
		arrows.clear();
		verify(client).clearHintArrow();
	}

	@Test
	public void logoutClearsOurArrowOnceSoItCannotBecomeStaleOnReconnect()
	{
		arrows.update(true, null, target);
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		arrows.clear();
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		arrows.clear();
		verify(client, times(1)).clearHintArrow();
	}
}

package com.levelinghelper;

import com.levelinghelper.model.ItemCategory;
import java.util.EnumSet;
import net.runelite.api.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ItemRulesTest
{
	private final Client client = mock(Client.class);
	private final ItemManager manager = mock(ItemManager.class);
	private final ItemRules rules = new ItemRules(client, manager);

	private ItemComposition item(int id, String name, boolean members)
	{
		ItemComposition item = mock(ItemComposition.class);
		when(item.getName()).thenReturn(name);
		when(item.getNote()).thenReturn(-1);
		when(item.getPlaceholderTemplateId()).thenReturn(-1);
		when(item.isMembers()).thenReturn(members);
		when(manager.getItemComposition(id)).thenReturn(item);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));
		return item;
	}

	@Test
	public void herbsAndSeedsMustBeUnnotedUsableAndAvailableOnThisWorld()
	{
		ItemComposition herb = item(ItemID.GRIMY_RANARR_WEED, "Grimy ranarr weed", true);
		when(client.getRealSkillLevel(Skill.HERBLORE)).thenReturn(24);
		assertFalse(rules.matches(ItemCategory.GRIMY_HERB, ItemID.GRIMY_RANARR_WEED));
		when(client.getRealSkillLevel(Skill.HERBLORE)).thenReturn(25);
		assertTrue(rules.matches(ItemCategory.GRIMY_HERB, ItemID.GRIMY_RANARR_WEED));
		when(herb.getNote()).thenReturn(ItemID.GRIMY_RANARR_WEED);
		assertFalse(rules.matches(ItemCategory.GRIMY_HERB, ItemID.GRIMY_RANARR_WEED));
		when(herb.getNote()).thenReturn(-1);
		when(herb.getPlaceholderTemplateId()).thenReturn(14401);
		assertFalse(rules.matches(ItemCategory.GRIMY_HERB, ItemID.GRIMY_RANARR_WEED));
		item(ItemID.RANARR_SEED, "Ranarr seed", true);
		when(client.getRealSkillLevel(Skill.FARMING)).thenReturn(31);
		assertFalse(rules.matches(ItemCategory.HERB_SEED, ItemID.RANARR_SEED));
		when(client.getRealSkillLevel(Skill.FARMING)).thenReturn(32);
		assertTrue(rules.matches(ItemCategory.HERB_SEED, ItemID.RANARR_SEED));
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		assertFalse(rules.matches(ItemCategory.HERB_SEED, ItemID.RANARR_SEED));
	}

	@Test
	public void weaponAndAmmunitionCategoriesUseActualEquipmentSlotsAndStats()
	{
		ItemComposition dart = item(ItemID.MITHRIL_DART, "Mithril dart", true);
		when(dart.isStackable()).thenReturn(true);
		when(manager.getItemStats(ItemID.MITHRIL_DART)).thenReturn(new ItemStats(true, 0, 0,
			ItemEquipmentStats.builder().slot(3).arange(8).rstr(7).build()));
		assertTrue(rules.matches(ItemCategory.RANGED_WEAPON, ItemID.MITHRIL_DART));
		assertTrue(rules.matches(ItemCategory.SELF_AMMO_WEAPON, ItemID.MITHRIL_DART));
		assertFalse(rules.matches(ItemCategory.AMMUNITION, ItemID.MITHRIL_DART));
		item(ItemID.RUNE_ARROW, "Rune arrow", false);
		when(manager.getItemStats(ItemID.RUNE_ARROW)).thenReturn(new ItemStats(true, 0, 0,
			ItemEquipmentStats.builder().slot(13).rstr(49).build()));
		assertTrue(rules.matches(ItemCategory.AMMUNITION, ItemID.RUNE_ARROW));
		assertFalse(rules.matches(ItemCategory.RANGED_WEAPON, ItemID.RUNE_ARROW));
	}

	@Test
	public void staleRunePouchVariablesNeverSupplyRunesWithoutACarriedPouch()
	{
		EnumComposition types = mock(EnumComposition.class);
		when(client.getEnum(982)).thenReturn(types);
		when(types.getIntValue(1)).thenReturn(ItemID.AIR_RUNE);
		when(client.getVarbitValue(Varbits.RUNE_POUCH_RUNE1)).thenReturn(1);
		when(client.getVarbitValue(Varbits.RUNE_POUCH_AMOUNT1)).thenReturn(500);
		when(client.getVarbitValue(Varbits.RUNE_POUCH_RUNE4)).thenReturn(1);
		when(client.getVarbitValue(Varbits.RUNE_POUCH_AMOUNT4)).thenReturn(250);
		doReturn(SupplyTrackerTest.container()).when(client).getItemContainer(InventoryID.INV);
		assertEquals(0, rules.pouchCount(ItemID.AIR_RUNE));
		doReturn(SupplyTrackerTest.container(new Item(ItemID.RUNE_POUCH, 1))).when(client).getItemContainer(InventoryID.INV);
		assertEquals(500, rules.pouchCount(ItemID.AIR_RUNE));
		doReturn(SupplyTrackerTest.container(new Item(ItemID.DIVINE_RUNE_POUCH, 1))).when(client).getItemContainer(InventoryID.INV);
		assertEquals(750, rules.pouchCount(ItemID.AIR_RUNE));
		assertEquals(0, rules.pouchCount(ItemID.FIRE_RUNE));
	}
	@Test
	public void hardLeatherOnlyCountsOnceHardleatherBodiesCanBeMade()
	{
		item(ItemID.HARD_LEATHER, "Hard leather", false);
		when(client.getRealSkillLevel(Skill.CRAFTING)).thenReturn(27);
		assertFalse(rules.matches(ItemCategory.LEATHER, ItemID.HARD_LEATHER));
		when(client.getRealSkillLevel(Skill.CRAFTING)).thenReturn(28);
		assertTrue(rules.matches(ItemCategory.LEATHER, ItemID.HARD_LEATHER));
	}

}

